function Canonicalize(P : List of Monomials):
  // 1. Sort by slope ascending, then by coeff ascending
  Sort P by (m.slope, m.coeff)

  // 2. Remove duplicates
  Deduped = empty list
  for m in P:
    if Deduped is empty or Deduped.last.slope != m.slope:
      Deduped.append(m)

  // 3. Extract Lower Convex Hull
  Hull = empty stack
  for p in Deduped:
    while Hull.size >= 2:
      p1 = Hull[second_to_last]
      p2 = Hull[last]
      if (p2.slope - p1.slope)*(p.coeff - p2.coeff) <= (p.slope - p2.slope)*(p2.coeff - p1.coeff):
         Hull.pop()
      else:
         break
    Hull.push(p)

  return Hull

algorithms.code:
def is_convex_turn(p1, p2, p3):
    dx1 = p2.slope - p1.slope
    dy1 = p2.coeff - p1.coeff
    dx2 = p3.slope - p2.slope
    dy2 = p3.coeff - p2.coeff
    return dx1 * dy2 > dx2 * dy1

def canonicalize(terms):
    sorted_terms = sorted(terms, key=lambda m: (m.slope, m.coeff))
    deduped = []
    for m in sorted_terms:
        if not deduped or deduped[-1].slope != m.slope:
            deduped.append(m)

    hull = []
    for p in deduped:
        while len(hull) >= 2 and not is_convex_turn(hull[-2], hull[-1], p):
            hull.pop()
        hull.append(p)
    return hull
